"use client";

/**
 * 改造自 shadcn 原装 base-lyra switch（https://ui.shadcn.com/r/styles/base-lyra/switch.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。缺省 `indicator`：拇指渲染 `data-motion="indicator"`，
 *    滑动由基础层的预设给出（位置 200ms ease-enter），删掉拇指上的 `transition-transform`。
 *    `none`：拇指直接跳到另一边。根元素的颜色过渡（`transition-all`）不变。
 * 此外只有格式化与两条 Biome 豁免注释，其余类名逐字保留。
 */
import { Switch as SwitchPrimitive } from "@base-ui/react/switch";
import { cn } from "cn";

/**
 * 开关支持的动效预设（ADR 0021）。缺省 `indicator`。
 * - `indicator`：拇指滑到另一边，200ms。
 * - `none`：拇指直接跳过去。
 */
type SwitchMotion = "none" | "indicator";

function Switch({
  className,
  size = "default",
  motion = "indicator",
  ...props
}: SwitchPrimitive.Root.Props & {
  size?: "sm" | "default";
  motion?: SwitchMotion;
}) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      data-size={size}
      className={cn(
        // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的轨道尺寸。
        "peer group/switch relative inline-flex shrink-0 items-center rounded-full border border-transparent transition-all outline-none group-has-[:focus-visible]/field-label:border-transparent group-has-[:focus-visible]/field-label:ring-0 after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-1 focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-1 aria-invalid:ring-destructive/20 data-[size=default]:h-[18.4px] data-[size=default]:w-[32px] data-[size=sm]:h-[14px] data-[size=sm]:w-[24px] dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 data-checked:bg-primary data-unchecked:bg-input dark:data-unchecked:bg-input/80 data-disabled:cursor-not-allowed data-disabled:opacity-50",
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        data-motion={motion === "none" ? undefined : motion}
        // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的拇指位移。
        className="pointer-events-none block rounded-full bg-background ring-0 group-data-[size=default]/switch:size-4 group-data-[size=sm]/switch:size-3 group-data-[size=default]/switch:data-checked:translate-x-[calc(100%-2px)] group-data-[size=sm]/switch:data-checked:translate-x-[calc(100%-2px)] dark:data-checked:bg-primary-foreground group-data-[size=default]/switch:data-unchecked:translate-x-0 group-data-[size=sm]/switch:data-unchecked:translate-x-0 dark:data-unchecked:bg-foreground"
      />
    </SwitchPrimitive.Root>
  );
}

export { Switch, type SwitchMotion };
